fn bmat(
    top_left: Vec<f32>, 
    top_right: Vec<f32>, 
    bottom_left: Vec<f32>, 
    bottom_right: Vec<f32>
) -> Vec<f32> {
    let n = top_left.len();
    // It's given that all arrays have the same length n.
    // Pre-allocate result vector to length 4n for efficiency.
    let mut result = Vec::with_capacity(4 * n);

    // Extend result in order with each input vector's elements
    result.extend(top_left);
    result.extend(top_right);
    result.extend(bottom_left);
    result.extend(bottom_right);

    result
}